# Cached data loading functions
@st.cache_data(ttl=app_config.cache_ttl, max_entries=app_config.max_cached_queries)
def cached_get_gene_expression(gene_name: str) -> pl.DataFrame:
    """Cached version of gene expression retrieval."""
    try:
        with st.spinner(f"Loading expression data for {gene_name}..."):
            return db.get_gene_expression(gene_name)
    except Exception as e:
        raise RuntimeError(f"Failed to load expression data for {gene_name}: {e}")

@st.cache_data(ttl=app_config.cache_ttl)
def cached_get_gene_transcripts(gene_name: str) -> pl.DataFrame:
    """Cached version of gene transcript retrieval."""
    try:
        return db.get_gene_transcripts(gene_name)
    except Exception as e:
        raise RuntimeError(f"Failed to load transcript data for {gene_name}: {e}")

